<div class="form-card card shadow-sm mx-auto"><div class="card-body p-4"><h1 class="h3">Login</h1><form method="post" action="<?=e(url('/login'))?>"><?=csrf_field()?><div class="mb-3"><label class="form-label" for="email">Email</label><input class="form-control" id="email" name="email" type="email" value="<?=e(old('email'))?>" required autocomplete="email" aria-invalid="<?=field_invalid('email')?>" aria-describedby="login-email-errors"><?php if(field_errors('email')):?><div id="login-email-errors" class="invalid-feedback d-block"><?=e(implode(' ',field_errors('email')))?></div><?php endif;?></div><div class="mb-3"><label class="form-label" for="login_password">Password</label><div class="input-group"><input class="form-control" id="login_password" name="password" type="password" required autocomplete="current-password"><button class="btn btn-outline-secondary" type="button" data-password-toggle="login_password" aria-label="Show password" aria-pressed="false">Show password</button></div></div><button class="btn btn-primary w-100" type="submit">Login</button></form><a class="d-block mt-3" href="<?=e(url('/forgot-password'))?>">Forgot password?</a></div></div>
